63	/// A Peer represents a reference to the router state associated with a peer
64	pub struct Peer<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> {
65	    inner: Arc<PeerInner<E, C, T, B>>,
66	}
