133	impl<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> DecryptionState<E, C, T, B> {
134	    fn new(peer: Peer<E, C, T, B>, keypair: &Arc<KeyPair>) -> DecryptionState<E, C, T, B> {
135	        DecryptionState {
136	            confirmed: AtomicBool::new(keypair.initiator),
137	            keypair: keypair.clone(),
138	            protector: spin::Mutex::new(AntiReplay::new()),
139	            peer,
140	        }
