144	impl<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> Drop for PeerHandle<E, C, T, B> {
145	    fn drop(&mut self) {
146	        let peer = &self.peer;
147	
148	        // remove from cryptkey router
149	
150	        self.peer.device.table.remove(peer);
151	
152	        // release ids from the receiver map
153	
154	        let mut keys = peer.keys.lock();
155	        let mut release = Vec::with_capacity(3);
156	
157	        if let Some(k) = keys.next.as_ref() {
158	            release.push(k.recv.id)
159	        }
160	        if let Some(k) = keys.current.as_ref() {
161	            release.push(k.recv.id)
162	        }
163	        if let Some(k) = keys.previous.as_ref() {
164	            release.push(k.recv.id)
165	        }
166	
167	        if !release.is_empty() {
168	            let mut recv = peer.device.recv.write();
169	            for id in &release {
170	                recv.remove(id);
171	            }
172	        }
173	
174	        // null key-material
175	
176	        keys.next = None;
177	        keys.current = None;
178	        keys.previous = None;
179	
180	        *peer.enc_key.lock() = None;
181	        *peer.endpoint.lock() = None;
182	
183	        log::debug!("peer dropped & removed from device");
184	    }
185	}
