187	pub fn new_peer<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>>(
188	    device: Device<E, C, T, B>,
189	    opaque: C::Opaque,
190	) -> PeerHandle<E, C, T, B> {
191	    // allocate peer object
192	    let peer = {
193	        Peer {
194	            inner: Arc::new(PeerInner {
195	                opaque,
196	                device,
197	                inbound: Queue::new(),
198	                outbound: Queue::new(),
199	                enc_key: spin::Mutex::new(None),
200	                endpoint: spin::Mutex::new(None),
201	                keys: spin::Mutex::new(KeyWheel {
202	                    next: None,
203	                    current: None,
204	                    previous: None,
205	                    retired: vec![],
206	                }),
207	                staged_packets: spin::Mutex::new(ArrayDeque::new()),
208	            }),
209	        }
210	    };
211	
212	    PeerHandle { peer }
213	}
