```rust
pub fn consume(&self) {
    // check if we are the first contender
    let pos = self.contenders.fetch_add(1, Ordering::SeqCst);
    if pos > 0 {
        assert!(usize::max_value() > pos, "contenders overflow");
        return;
    }

    // enter the critical section
    let mut contenders = 1; // myself
